const item = $input.first().json;
const body = item.body || item;

// Só processa o evento de mensagens novas
const ev = String(body.event || '').toLowerCase().replace('_', '.');
if (ev && ev !== 'messages.upsert') return [];

const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
if (!remoteJid || !key.id) return [];

// Ignora grupos e broadcast de status
if (remoteJid.includes('@g.us') || remoteJid.includes('broadcast')) return [];

const messageType = data.messageType || '';
if (['reactionMessage', 'protocolMessage', 'senderKeyDistributionMessage', 'editedMessage'].includes(messageType)) {
  return [];
}

const senderName = data.pushName || 'Gestor Magia Festeira';
const senderPhone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

// Lista de gestores conhecidos
const GESTORES = [
  '5511976371317', '551176371317',
  '5511976330783', '551176330783',
  '5511968581802', '551168581802',
  '5511977823876', '551177823876',
  '5511991049200', '551191049200'
];

const fromMe = key.fromMe === true;
const isGestorPhone = GESTORES.includes(senderPhone);

const m = data.message || {};
const pick = (v) => (typeof v === 'string' ? v : '');
const messageText = pick(m.conversation) ||
                    pick(m.extendedTextMessage?.text) ||
                    pick(m.imageMessage?.caption) ||
                    pick(m.videoMessage?.caption) ||
                    pick(m.documentWithCaptionMessage?.message?.documentMessage?.caption) ||
                    pick(body.message) || pick(body.text) || '';
const hasText = messageText.trim().length > 0;

if (!hasText && !messageType) return [];

// 🛡️ DETECÇÃO DE MENSAGENS AUTOMÁTICAS (Meta Ads CTWA / WhatsApp Business / Auto-resposta):
// Mensagens como "Olaaa, obrigado por nos procurar, em instantes te retornaremos." NUNCA são intervenção humana!
const ehMensagemAutomatica = /obrigad[ao] por nos procurar|em instantes te retornaremos|em instantes retornaremos|mensagem autom[áa]tica|hor[áa]rio de atendimento|estamos ausentes/i.test(messageText);

// Se for mensagem automática, descarta no filtro para NUNCA pausar o bot e permitir que a Sofia atenda normalmente!
if (fromMe && ehMensagemAutomatica) {
  return [];
}

// Se fromMe for true MAS a conversa é consigo mesmo ou com o número da Magia / gestor,
// NÃO é intervenção de atendente em cliente! É o gestor usando o WhatsApp da Magia!
const ehIntervencaoAtendente = fromMe && !isGestorPhone;

const now = new Date();
const currentDateTime = now.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    senderName,
    remoteJid,
    senderPhone,
    messageType,
    messageText,
    hasText,
    fromMe,
    ehIntervencaoAtendente,
    messageId: key.id,
    currentDateTime,
    chatInput: messageText
  }
}];

let raw = '';
try {
  raw = typeof query !== 'undefined' ? query : '';
} catch (e) {
  raw = '';
}

let params = {};
if (typeof raw === 'string' && raw.trim().startsWith('{')) {
  try {
    params = JSON.parse(raw);
  } catch (e) {
    params = {};
  }
} else if (typeof raw === 'object' && raw !== null) {
  params = raw;
}

const payload = {
  customerName: params.customerName || params.nome || 'Cliente WhatsApp',
  customerPhone: String(params.customerPhone || params.telefone || params.cel || '').replace(/\D/g, ''),
  customerDocument: params.customerDocument || params.cpf || params.document || null,
  customerAddress: params.customerAddress || params.enderecoCliente || params.enderecoResidencial || null,
  customerEmail: params.customerEmail || params.email || null,

  eventName: params.eventName || params.nomeEvento || params.dadosEvento || null,
  eventDate: params.eventDate || params.data || '',
  pickupDate: params.pickupDate || params.dataRetirada || params.eventDate || params.data || '',
  returnDate: params.returnDate || params.dataDevolucao || params.eventDate || params.data || '',
  startTime: params.startTime || params.horarioInicio || null,
  endTime: params.endTime || params.horarioTermino || null,

  themeQuery: params.themeQuery || params.tema || params.temaEscolhido || params.themeName || '',
  total: Number(String(params.total || params.valorTotal || params.valor || 0).replace(/[^0-9.,]/g, '').replace(',', '.')),
  paid: Number(String(params.paid || params.sinal || params.entrada || 0).replace(/[^0-9.,]/g, '').replace(',', '.')),
  paymentMethod: params.paymentMethod || params.formaPagamento || 'pix',
  paymentTerms: params.paymentTerms || params.condicaoPagamento || params.formaPagamento || null,
  extraItems: params.extraItems || params.itensExtras || null,

  deliveryLocation: params.deliveryLocation || params.enderecoEvento || params.localEntrega || params.local || null,
  notes: params.notes || params.observacao || params.observacoes || null,
  status: params.status || (params.historico || params.isHistorico ? 'historico' : undefined),
  forceOverride: params.forceOverride !== undefined ? params.forceOverride : true
};

