// Foi o bot que enviou? (Supabase REST)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const item = $input.first().json;
const msgId = item.messageId || '';

try {
  if (msgId) {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_enviadas?msg_id=eq.${encodeURIComponent(msgId)}&limit=1`,
