    }
  }
  return [{ json: { ...item, eh_bot: false } }];
} catch (e) {
  return [{ json: { ...item, eh_bot: false } }];
}

// Reativar bot (Supabase REST)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const filtro = $('Filtro & Sanitização WhatsApp').first().json;
const remoteJid = filtro.remoteJid || '';

try {
  if (remoteJid) {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}`,
      headers: { 'apikey': anonKey, 'Authorization': `Bearer ${anonKey}` },
      json: true
    });
  }
} catch (e) {}

return [{ json: $input.first().json }];

const NOTIFICAR = ['5511976330783', '5511977823876'];
const f = $('Filtro & Sanitização WhatsApp').first().json;
const text = '✅ *Sofia reativada* para wa.me/' + f.senderPhone + '. Ela volta a responder as próximas mensagens desse cliente.';
return NOTIFICAR.map(n => ({ json: { number: n, text, delay: 500 } }));

// Pausar: humano respondeu (Supabase REST)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const filtro = $('Filtro & Sanitização WhatsApp').first().json;
const remoteJid = filtro.remoteJid || '';
const msgTexto = String(filtro.messageText || '').toLowerCase();

// Defesa em profundidade: NUNCA pausa o bot por mensagens automáticas conhecidas (Meta Ads / Auto-resposta)
if (
  msgTexto.includes('obrigado por nos procurar') ||
  msgTexto.includes('em instantes te retornaremos') ||
  msgTexto.includes('em instantes retornaremos') ||
  msgTexto.includes('mensagem automática')
) {
  return [{ json: $input.first().json }];
}

try {
  if (remoteJid) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${supabaseUrl}/rest/v1/bot_pausa`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates'
      },
      body: {
        remote_jid: remoteJid,
        motivo: 'humano_respondeu',
        paused_at: new Date().toISOString()
      },
      json: true,
      timeout: 4000
    });
  }
} catch (e) {}

return [{ json: $input.first().json }];

const it = $input.first().json;
const jid = it.remoteJid || '';
// Ignora grupos, listas de transmissao e canais
if (jid.endsWith('@g.us') || jid.includes('@broadcast') || jid.includes('@newsletter')) return [];

const t = it.messageType;
const MEDIA = ['imageMessage', 'videoMessage', 'stickerMessage', 'documentMessage', 'documentWithCaptionMessage',
               'locationMessage', 'liveLocationMessage', 'contactMessage', 'contactsArrayMessage', 'ptvMessage'];
let kind;
if (t === 'audioMessage') kind = 'audio';
else if (t === 'imageMessage') kind = 'image';
else if (MEDIA.includes(t)) kind = 'media';
else if (it.hasText) kind = 'text';
else return [];

return [{ json: { ...it, kind, mediaTipo: t } }];

// Bot pausado? (Supabase REST)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const item = $input.first().json;
const remoteJid = item.remoteJid || '';

try {
  if (remoteJid) {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}&limit=1`,
      headers: { 'apikey': anonKey, 'Authorization': `Bearer ${anonKey}` },
      json: true
    });
    const pausado = Array.isArray(res) && res.length > 0;
    return [{ json: { ...item, pausado } }];
  }
  return [{ json: { ...item, pausado: false } }];
} catch (e) {
  return [{ json: { ...item, pausado: false } }];
}

const b64 = $input.first().json.base64;
if (!b64) return [{ json: { falhou: true } }];
const buf = Buffer.from(b64, 'base64');
const bin = await this.helpers.prepareBinaryData(buf, 'audio.ogg', 'audio/ogg');
return [{ json: {}, binary: { data: bin } }];

let base = {};
try {
  base = $('Cliente: classifica').first().json;
} catch (e) {
  base = $input.first().json;
}
const t = String($input.first().json.text || '').trim();
return [{ json: { ...base, messageText: t ? '[áudio transcrito] ' + t : '[ÁUDIO NÃO COMPREENDIDO]', foiAudio: true } }];

const NOTIFICAR = ['5511976330783', '5511977823876'];
const d = $input.first().json;
const tipos = { imageMessage: 'uma imagem', videoMessage: 'um vídeo', stickerMessage: 'uma figurinha',
  documentMessage: 'um documento', documentWithCaptionMessage: 'um documento', locationMessage: 'uma localização',
  liveLocationMessage: 'uma localização', contactMessage: 'um contato', contactsArrayMessage: 'contatos', ptvMessage: 'um vídeo' };
const tipo = tipos[d.mediaTipo] || 'uma mídia';
const legenda = d.hasText ? '\n💬 Legenda: ' + String(d.messageText).slice(0, 300) : '';
const text = '📎 *Cliente enviou ' + tipo + '*\n👤 ' + d.senderName + '\n📱 wa.me/' + d.senderPhone + legenda +
  '\n\n🤖 A Sofia não consegue ver isso e ficou em silêncio. Vale responder por aqui.';
return NOTIFICAR.map(n => ({ json: { number: n, text, delay: 800 } }));

// Buffer: guardar (Supabase REST)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const item = $input.first().json;
const remoteJid = item.remoteJid || '';
const messageId = item.messageId || ('msg_' + Date.now());
const messageText = String(item.messageText || '').trim();

try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/bot_buffer`,
    headers: {
      'apikey': anonKey,
      'Authorization': `Bearer ${anonKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: {
      remote_jid: remoteJid,
      msg_id: messageId,
      texto: messageText
    },
    json: true,
    timeout: 4000
  });

  const inserted = Array.isArray(res) ? res[0] : res;
  return [{
    json: {
      ...item,
      bufferId: inserted?.id
    }
  }];
} catch (err) {
  return [{
    json: {
      ...item,
      bufferId: null,
      bufferError: err.message
    }
  }];
}

// Buffer: sou a última? (Supabase REST - Otimizado e com timeout seguro)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const item = $input.first().json;
const remoteJid = item.remoteJid || '';
const myBufferId = item.bufferId;

// Se não tiver bufferId (fallback caso inserção tenha falhado), repassa normalmente com texto original
if (!myBufferId) {
  return [{
    json: {
      ...item,
      texto: item.messageText || ''
    }
  }];
}

try {
  // Se for comando de reset, despausa imediatamente no Supabase
  const isResetCmd = /(?:^|\n|\s)[#/](?:reset|limpar)\b/i.test(item.messageText || '');
  if (isResetCmd) {
    try {
      await this.helpers.httpRequest({
        method: 'DELETE',
        url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}`,
        headers: { 'apikey': anonKey, 'Authorization': `Bearer ${anonKey}` },
        timeout: 3000
      });
    } catch (e) {}
  }

  // 1 & 2. Executa em paralelo a verificação de pausa e busca de mensagens pendentes
  const [pausaRes, pendingRes] = await Promise.all([
    this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}&limit=1`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`
      },
      json: true,
      timeout: 4000
    }),
    this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_buffer?remote_jid=eq.${encodeURIComponent(remoteJid)}&processado=eq.false&order=id.asc`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`
      },
      json: true,
      timeout: 4000
    })
  ]);

  // Se o bot está pausado para este cliente (atendente humano assumiu ou handoff realizado)
  if (Array.isArray(pausaRes) && pausaRes.length > 0) {
    const row = pausaRes[0];
    const pausedAt = row.paused_at ? new Date(row.paused_at) : new Date(0);
    const CINCO_DIAS_MS = 5 * 24 * 60 * 60 * 1000; // 5 dias de inatividade (432.000.000 ms)
    const diferenca = Date.now() - pausedAt.getTime();

    // Se passaram mais de 5 dias sem nova interação, a pausa expira automaticamente!
    if (diferenca > CINCO_DIAS_MS) {
      try {
        await this.helpers.httpRequest({
          method: 'DELETE',
          url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}`,
          headers: {
            'apikey': anonKey,
            'Authorization': `Bearer ${anonKey}`
          },
          json: true,
          timeout: 3000
        });
      } catch (e) {}
