    mensagens[i] = mensagens[i].replace(/([^.!?\n]*(?:para quando\b|qual (?:a )?data\b)[^?]*\??)/gi, '').trim();
  }

  // Guardrail anti-questionário: se ainda não sabemos o nome ou o tema, remove perguntas secundárias indevidas
  if (/como posso te chamar/i.test(mensagens[i])) {
    mensagens[i] = mensagens[i].replace(/\s*e\s+qual\s+tema\s+[^?]*\?/gi, '');
    mensagens[i] = mensagens[i].replace(/\s*para\s+quando\s+(seria|é)\s+[^?]*\?/gi, '');
  }

  // Higienização completa contra cortes de frases e pontuações órfãs
  mensagens[i] = mensagens[i]
    .replace(/,\s+([Ee]\s+)/g, ' $1')
    .replace(/\s{2,}/g, ' ')
    .replace(/^[,;:\s]+(?:e|ou)\s+/i, '')
    .replace(/[,;:\s]+(?:e|ou)\s*$/i, '')
    .replace(/^[,;:\s]+|[,;:\s]+$/g, '')
    .trim();

  // Se terminar em vírgula ou dois pontos após remoções, ajusta para ponto
  mensagens[i] = mensagens[i].replace(/[,;:]+$/, '.').trim();

  // Ajusta maiúsculas após pontuação
  mensagens[i] = mensagens[i].replace(/([.!?]\s*)([a-z])/g, (m, p1, p2) => p1 + (p1.endsWith(' ') ? '' : ' ') + p2.toUpperCase());
}
mensagens = mensagens.filter(m => m.length > 0);

// Deduplicação de mensagens idênticas no mesmo turno
mensagens = [...new Set(mensagens)];

// Gatilho de segurança: aciona atendente quando indicado pelo modelo ou por mensagem conclusiva
