function getModo(phone) {
  if (!phone) return null;
  if (CONFIG_MODO_GESTORES[phone]) return CONFIG_MODO_GESTORES[phone];

  // Variação sem o 9 (13 -> 12 dígitos)
  if (phone.length === 13 && phone.startsWith('55')) {
    const sem9 = phone.slice(0, 4) + phone.slice(5);
    if (CONFIG_MODO_GESTORES[sem9]) return CONFIG_MODO_GESTORES[sem9];
  }
  // Variação com o 9 (12 -> 13 dígitos)
  if (phone.length === 12 && phone.startsWith('55')) {
