// Buffer: sou a última? (Supabase REST - Otimizado e com timeout seguro)
const supabaseUrl = 'https://pajxnizsutuaonqpdiut.supabase.co';
const anonKey = 'sb_publishable_ReR3azf81Bu7eYHiExaXjw_tOmn90MY';

const item = $input.first().json;
const remoteJid = item.remoteJid || '';
const myBufferId = item.bufferId;

// Se não tiver bufferId (fallback caso inserção tenha falhado), repassa normalmente com texto original
if (!myBufferId) {
  return [{
    json: {
      ...item,
      texto: item.messageText || ''
    }
  }];
}

try {
  // Se for comando de reset, despausa imediatamente no Supabase
  const isResetCmd = /(?:^|\n|\s)[#/](?:reset|limpar)\b/i.test(item.messageText || '');
  if (isResetCmd) {
    try {
      await this.helpers.httpRequest({
        method: 'DELETE',
        url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}`,
        headers: { 'apikey': anonKey, 'Authorization': `Bearer ${anonKey}` },
        timeout: 3000
      });
    } catch (e) {}
  }

  // 1 & 2. Executa em paralelo a verificação de pausa e busca de mensagens pendentes
  const [pausaRes, pendingRes] = await Promise.all([
    this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}&limit=1`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`
      },
      json: true,
      timeout: 4000
    }),
    this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/bot_buffer?remote_jid=eq.${encodeURIComponent(remoteJid)}&processado=eq.false&order=id.asc`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`
      },
      json: true,
      timeout: 4000
    })
  ]);

  // Se o bot está pausado para este cliente (atendente humano assumiu ou handoff realizado)
  if (Array.isArray(pausaRes) && pausaRes.length > 0) {
    const row = pausaRes[0];
    const pausedAt = row.paused_at ? new Date(row.paused_at) : new Date(0);
    const CINCO_DIAS_MS = 5 * 24 * 60 * 60 * 1000; // 5 dias de inatividade (432.000.000 ms)
    const diferenca = Date.now() - pausedAt.getTime();

    // Se passaram mais de 5 dias sem nova interação, a pausa expira automaticamente!
    if (diferenca > CINCO_DIAS_MS) {
      try {
        await this.helpers.httpRequest({
          method: 'DELETE',
          url: `${supabaseUrl}/rest/v1/bot_pausa?remote_jid=eq.${encodeURIComponent(remoteJid)}`,
          headers: {
            'apikey': anonKey,
            'Authorization': `Bearer ${anonKey}`
          },
          json: true,
          timeout: 3000
        });
      } catch (e) {}
      // Pausa removida: a Sofia volta a atender a próxima mensagem do cliente!
    } else {
      // Pausa ativa dentro de 5 dias: marca mensagens do buffer como processadas para não acumular lixo
      try {
        const pendingList = Array.isArray(pendingRes) ? pendingRes : [];
        const idsToMark = pendingList.map(p => p.id).filter(Boolean);
        if (idsToMark.length > 0) {
          await this.helpers.httpRequest({
            method: 'PATCH',
            url: `${supabaseUrl}/rest/v1/bot_buffer?id=in.(${idsToMark.join(',')})`,
            headers: {
              'apikey': anonKey,
              'Authorization': `Bearer ${anonKey}`,
              'Content-Type': 'application/json'
            },
            body: { processado: true },
            json: true,
            timeout: 3000
          });
        }
      } catch (e) {}

      // Pausa ativa dentro de 5 dias: o bot silencia completamente para o humano atender!
      return [{ json: { texto: null, motivo: 'bot_pausado' } }];
    }
  }

  const pendingList = Array.isArray(pendingRes) ? pendingRes : [];

  // Se houver mensagens pendentes, verifica se esta execução é a última
  if (pendingList.length > 0) {
    const latestId = pendingList[pendingList.length - 1].id;
    // Se existe uma mensagem posterior a esta, esta execução encerra para deixar a mais recente responder tudo junto
    if (latestId && latestId > myBufferId) {
      return [{ json: { texto: null, motivo: 'nao_e_ultima' } }];
    }
  }

  // Esta execução É a última! Junta todo o texto acumulado em ordem cronológica
  const combinedText = pendingList.length > 0 
    ? pendingList.map(p => p.texto).filter(Boolean).join('\n') 
    : (item.messageText || '');

  const finalText = combinedText.trim() || (item.messageText || '');

  // Marca todas as mensagens pendentes como processadas no Supabase
  const idsToMark = pendingList.map(p => p.id).filter(Boolean);
  if (idsToMark.length > 0) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${supabaseUrl}/rest/v1/bot_buffer?id=in.(${idsToMark.join(',')})`,
      headers: {
        'apikey': anonKey,
        'Authorization': `Bearer ${anonKey}`,
        'Content-Type': 'application/json'
      },
      body: { processado: true },
      json: true,
      timeout: 4000
    });
  }

  return [{
    json: {
      ...item,
      texto: finalText,
      messageText: finalText,
      bufferMsgCount: pendingList.length || 1
    }
  }];
} catch (err) {
  // Fallback à prova de falhas: NUNCA deixa o cliente no vácuo se o Supabase/runner falhar
  return [{
    json: {
      ...item,
      texto: item.messageText || '',
      bufferError: err.message
    }
  }];
}

