const term = raw.trim();

function normalize(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // remove acentos
    .toLowerCase()
    .replace(/[-_.,;:!?/]+/g, ' ')   // hífens, pontuações e traços viram espaço
    .replace(/\s+/g, ' ')
    .trim();
}

try {
  // 1. Busca catálogo completo de nomes oficiais para matching semântico e fonético
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://sistema-magia-festeira-kaldiris-financial-os.vercel.app/api/v1/themes?namesOnly=true',
    headers: { 'x-api-key': 'mf_live_sec_magiafesteira2026' },
    json: true
  });

  const allNames = (res && res.names && Array.isArray(res.names)) ? res.names : [];

  if (!term || term.toLowerCase() === 'todos' || term.length < 2) {
    return 'Catálogo oficial da Magia Festeira (' + allNames.length + ' temas): ' + allNames.join(', ');
  }

  const normTerm = normalize(term);
  const termTokens = normTerm.split(' ').filter(w => w.length >= 2);

  // Mapeamento de personagens e sinônimos populares
  const synonymMap = {
    'spider': 'homem aranha',
    'spiderman': 'homem aranha',
    'spider man': 'homem aranha',
    'aranha': 'homem aranha',
    'minion': 'minions'
  };

  let searchTokens = [...termTokens];
  for (const [k, v] of Object.entries(synonymMap)) {
    if (normTerm.includes(k)) {
      searchTokens.push(...v.split(' '));
    }
  }

  // Busca inteligente desconsiderando hífens, acentos e pontuação
  const matches = allNames.filter(themeName => {
    const normTheme = normalize(themeName);

    // 1. Match exato normalizado (ex: "homem aranha" === "homem aranha")
    if (normTheme === normTerm) return true;

    // 2. Substring direta normalizada (ex: "aranha" está em "homem aranha")
    if (normTheme.includes(normTerm) || normTerm.includes(normTheme)) return true;

    // 3. Todos os tokens da busca estão no tema
    if (searchTokens.length >= 2) {
      const allFound = searchTokens.every(st => normTheme.includes(st));
      if (allFound) return true;
    }

    // 4. Tokens comuns significativos
    const themeTokens = normTheme.split(' ').filter(w => w.length >= 2);
    const common = themeTokens.filter(t => searchTokens.includes(t));
    if (common.length >= 2) return true;
    if (searchTokens.length === 1 && themeTokens.includes(searchTokens[0])) return true;

    return false;
  });

  if (matches.length > 0) {
    return 'Temas encontrados no catálogo oficial da Magia Festeira: ' + matches.join(', ');
  }

  // Fallback para endpoint de busca da API
  try {
