  if (lower.startsWith('#assessor') || lower.startsWith('/assessor') || lower.startsWith('#gestor') || lower.startsWith('/gestor')) {
    destino = 'assessor';
    text = text.replace(/^[#/](assessor|gestor)\s*/i, '').trim();
    if (!text) {
      text = 'Modo Assessor ativado. Olá, como posso te ajudar hoje?';
    }
  } else if (lower.startsWith('#sofia') || lower.startsWith('/sofia')) {
    destino = 'sofia';
    text = text.replace(/^[#/]sofia\s*/i, '').trim();
    if (!text) {
      text = 'Olá Sofia!';
    }
  }
  // Detecção inteligente de formulários de clientes colados pelo gestor ou comandos de gestão
  else if (
    ((lower.includes('*nome*') || lower.includes('nome:')) && (lower.includes('*cpf*') || lower.includes('cpf:') || lower.includes('dados do evento') || lower.includes('dados de locação') || lower.includes('tema escolhido'))) ||
    lower.includes('último cliente') ||
    lower.includes('ultimo cliente') ||
    lower.includes('relatório') ||
    lower.includes('relatorio') ||
    lower.includes('faturamento') ||
    lower.includes('quantas locações') ||
    lower.includes('quantas locacoes') ||
    lower.includes('lançar locação') ||
    lower.includes('lancar locacao') ||
    lower.includes('criar orçamento') ||
    lower.includes('criar orcamento') ||
    lower.includes('saldo') ||
    lower.startsWith('/relatorio') ||
    lower.startsWith('/temas') ||
    lower.startsWith('/locacao')
  ) {
    destino = 'assessor';
  }
}

return [{
  json: {
    ...item,
    messageText: text,
    chatInput: text,
    destino: destino, // 'assessor' ou 'sofia'
    isGestor: isGestor,
    modoAtivo: destino
  }
}];

