parameters.jsCode:
const clienteItem = $('Cliente: classifica').first().json;
const visionOutput = $input.first().json;

let visionParsed = null;
try {
  const content = visionOutput?.choices?.[0]?.message?.content;
  if (content) visionParsed = JSON.parse(content);
} catch (e) {}

const tema = visionParsed?.tema || null;
const desc = visionParsed?.descricao || '';
const legenda = (clienteItem.messageText || '').trim();

let textoFinal = '';
if (tema) {
  textoFinal = `[Foto de referência enviada pelo cliente: Tema identificado "${tema}". Detalhes visuais: ${desc}]` +
    (legenda ? `\nLegenda do cliente: ${legenda}` : `\nO cliente enviou esta foto perguntando da decoração.`);
} else if (desc) {
  textoFinal = `[Foto de referência enviada pelo cliente: Referência visual de festa com ${desc}. Tema não identificado com certeza.]` +
    (legenda ? `\nLegenda do cliente: ${legenda}` : `\nO cliente enviou esta foto como referência.`);
} else {
  textoFinal = `[Foto enviada pelo cliente]` + (legenda ? `\nLegenda: ${legenda}` : '');
}

return [{
  json: {
    ...clienteItem,
    messageText: textoFinal,
    chatInput: textoFinal,
    temaIdentificadoFoto: tema,
    fotoDescricao: desc
  }
}];
